<?php require '../config/database.php';auth();$rows=$pdo->query('SELECT * FROM products ORDER BY id DESC')->fetchAll();?><!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><link rel="stylesheet" href="../assets/css/style.css"><main><h1>المنتجات والمخزون</h1><a class="btn" href="add.php">إضافة منتج</a><table><tr><th>#</th><th>المنتج</th><th>الباركود</th><th>التصنيف</th><th>سعر الشراء</th><th>سعر البيع</th><th>الكمية</th><th>إجراء</th></tr><?php foreach($rows as $r):?><tr><td><?=$r['id']?></td><td><?=htmlspecialchars($r['name'])?></td><td><?=$r['barcode']?></td><td><?=$r['category']?></td><td><?=$r['purchase_price']?></td><td><?=$r['sale_price']?></td><td><?=$r['quantity']?></td><td><a href="edit.php?id=<?=$r['id']?>">تعديل</a> | <a href="delete.php?id=<?=$r['id']?>">حذف</a></td></tr><?php endforeach;?></table></main>
